import sys

CAP = 8
LOW = 4
CHUNKS = [b'aaa', b'bbb', b'cc', b'd', b'e', b'fff', b'gg']


class Publisher:
    def __init__(self, chunks, capacity=CAP, low=LOW):
        self.chunks = list(chunks)
        self.capacity = capacity
        self.low = low
        self.log = []
        self.accepted = []
        self.pending = []
        self.occupied = 0
        self.paused = False
        self.terminal = None

    def offer(self, seq, data):
        if self.terminal is not None:
            result = 'terminal'
        elif len(data) > self.capacity:
            result = 'too_large'
        else:
            if self.paused:
                if self.occupied <= self.low:
                    self.paused = False
                else:
                    self.log.append(('offer', seq, data, 'paused'))
                    return 'paused'
            if self.occupied + len(data) > self.capacity:
                self.paused = True
                result = 'paused'
            else:
                self.accepted.append((seq, data))
                self.pending.append((seq, data))
                self.occupied += len(data)
                result = 'accepted'
        self.log.append(('offer', seq, data, result))
        return result

    def flush_one(self):
        if self.terminal is not None or not self.pending:
            return None
        seq, data = self.pending.pop(0)
        self.occupied -= len(data)
        self.log.append(('flush', seq, data))
        if self.paused and self.occupied <= self.low:
            self.paused = False
        return data

    def finish(self, reason='FINAL'):
        if self.terminal is not None:
            return False
        if reason == 'FINAL':
            if self.pending or len(self.accepted) != len(self.chunks):
                return False
        self.terminal = reason
        self.log.append(('terminal', reason))
        return True


def expected_result(seq, data, capacity, low, next_accept, occupied, paused):
    if seq != next_accept:
        return 'bad_seq', paused
    if len(data) > capacity:
        return 'too_large', paused
    if paused and occupied <= low:
        paused = False
    if occupied + len(data) > capacity:
        return 'paused', True
    return 'accepted', paused


def verify(log, expected, terminal_expected, capacity=CAP, low=LOW):
    errors = []
    occupied = 0
    accepted = {}
    next_accept = 0
    next_flush = 0
    paused = False
    terminal = None
    flushed = set()
    for pos, event in enumerate(log):
        kind = event[0]
        if kind == 'terminal':
            if terminal is not None:
                errors.append('duplicate terminal at %d' % pos)
            else:
                terminal = event[1]
            continue
        if terminal is not None:
            errors.append('event after terminal at %d' % pos)
            continue
        if kind == 'offer':
            seq, data, result = event[1], event[2], event[3]
            exp, paused = expected_result(seq, data, capacity, low, next_accept, occupied, paused)
            if result != exp:
                errors.append('offer seq %d result %s expected %s at %d' % (seq, result, exp, pos))
            if result == 'accepted':
                if seq != next_accept:
                    errors.append('accepted bad seq %d expected %d' % (seq, next_accept))
                elif seq >= len(expected) or data != expected[seq]:
                    errors.append('accepted wrong payload seq %d' % seq)
                else:
                    accepted[seq] = data
                    occupied += len(data)
                    next_accept += 1
            elif result == 'paused':
                paused = True
            if occupied > capacity:
                errors.append('occupancy %d > capacity %d at %d' % (occupied, capacity, pos))
        elif kind == 'flush':
            seq, data = event[1], event[2]
            if seq != next_flush:
                errors.append('flush seq %d expected %d at %d' % (seq, next_flush, pos))
            if seq in flushed:
                errors.append('duplicate flush seq %d' % seq)
            if seq not in accepted:
                errors.append('flush unaccepted seq %d' % seq)
            elif accepted[seq] != data:
                errors.append('flush wrong payload seq %d' % seq)
            if seq < len(expected) and expected[seq] != data:
                errors.append('flush differs from reference seq %d' % seq)
            occupied -= len(data)
            next_flush += 1
            flushed.add(seq)
            if occupied < 0:
                errors.append('negative occupancy at %d' % pos)
            if paused and occupied <= low:
                paused = False
        else:
            errors.append('unknown event %s' % kind)
    if terminal is None:
        errors.append('missing terminal')
    elif terminal != terminal_expected:
        errors.append('terminal %s expected %s' % (terminal, terminal_expected))
    if terminal_expected == 'FINAL':
        if next_accept != len(expected):
            errors.append('final accepted %d expected %d' % (next_accept, len(expected)))
        if next_flush != len(expected):
            errors.append('final flushed %d expected %d' % (next_flush, len(expected)))
        if occupied != 0:
            errors.append('final occupancy %d' % occupied)
    if terminal_expected == 'CANCEL':
        if next_flush > len(expected):
            errors.append('cancel flushed beyond reference')
    return errors


def drive_to_final(p):
    for seq, data in enumerate(p.chunks):
        while True:
            result = p.offer(seq, data)
            if result == 'accepted':
                break
            if result != 'paused':
                return False
            if p.flush_one() is None:
                return False
    while p.pending:
        if p.flush_one() is None:
            return False
    return p.finish('FINAL')


def drive_to_cancel(p):
    for seq, data in enumerate(p.chunks):
        result = p.offer(seq, data)
        if result == 'paused':
            break
        if result != 'accepted':
            return False
    while p.pending:
        p.flush_one()
    return p.finish('CANCEL')


def flushed_bytes(p):
    return sum(len(event[2]) for event in p.log if event[0] == 'flush')


class DuplicateFlushPublisher(Publisher):
    def __init__(self, chunks, capacity=CAP, low=LOW):
        super().__init__(chunks, capacity, low)
        self.duplicated = False

    def flush_one(self):
        if not self.duplicated and self.pending and self.pending[0][0] == 1:
            self.duplicated = True
            seq, data = self.pending[0]
            self.log.append(('flush', seq, data))
            return data
        return super().flush_one()


class DropPublisher(Publisher):
    def __init__(self, chunks, capacity=CAP, low=LOW):
        super().__init__(chunks, capacity, low)
        self.dropped = False

    def offer(self, seq, data):
        if seq == 2 and not self.dropped:
            self.dropped = True
            self.accepted.append((seq, data))
            self.log.append(('offer', seq, data, 'accepted'))
            return 'accepted'
        return super().offer(seq, data)


class EarlyFinalPublisher(Publisher):
    def __init__(self, chunks, capacity=CAP, low=LOW):
        super().__init__(chunks, capacity, low)
        self.early = False

    def finish(self, reason='FINAL'):
        if reason == 'FINAL' and not self.early:
            self.early = True
            self.terminal = 'FINAL'
            self.log.append(('terminal', 'FINAL'))
            return True
        return super().finish(reason)


class OverflowPublisher(Publisher):
    def __init__(self, chunks, capacity=CAP, low=LOW):
        super().__init__(chunks, capacity, low)
        self.overflowed = False

    def offer(self, seq, data):
        if seq == 2 and not self.overflowed:
            self.overflowed = True
            self.accepted.append((seq, data))
            self.pending.append((seq, data))
            self.occupied += len(data)
            self.log.append(('offer', seq, data, 'accepted'))
            return 'accepted'
        return super().offer(seq, data)


def main():
    ok = True

    p = Publisher(CHUNKS)
    if not drive_to_final(p):
        print('normal drive failed')
        return 1
    errors = verify(p.log, CHUNKS, 'FINAL')
    for error in errors:
        print('normal error: %s' % error)
        ok = False
    pauses = sum(1 for event in p.log if event[0] == 'offer' and event[3] == 'paused')
    print('normal: chunks=%d bytes=%d pauses=%d terminal=%s' % (
        len(CHUNKS), flushed_bytes(p), pauses, p.terminal))

    c = Publisher(CHUNKS)
    if not drive_to_cancel(c):
        print('cancel drive failed')
        return 1
    errors = verify(c.log, CHUNKS, 'CANCEL')
    for error in errors:
        print('cancel error: %s' % error)
        ok = False
    print('cancel: accepted=%d flushed_bytes=%d terminal=%s' % (
        len(c.accepted), flushed_bytes(c), c.terminal))

    z = Publisher([])
    if not z.finish('FINAL'):
        print('empty final finish failed')
        return 1
    errors = verify(z.log, [], 'FINAL')
    for error in errors:
        print('empty final error: %s' % error)
        ok = False
    print('empty_final: events=%d errors=%d' % (len(z.log), len(errors)))

    t = Publisher([b'123456789'])
    if t.offer(0, b'123456789') != 'too_large':
        print('oversize chunk was not rejected')
        ok = False
    else:
        print('oversize: result=too_large')

    d = DuplicateFlushPublisher(CHUNKS)
    if not drive_to_final(d):
        print('duplicate publisher drive failed')
        return 1
    errors = verify(d.log, CHUNKS, 'FINAL')
    if not errors:
        print('negative control duplicate flush was not detected')
        ok = False
    else:
        print('negative duplicate_flush detected: %s' % errors[0])

    d = DropPublisher(CHUNKS)
    if not drive_to_final(d):
        print('drop publisher drive failed')
        return 1
    errors = verify(d.log, CHUNKS, 'FINAL')
    if not errors:
        print('negative control dropped chunk was not detected')
        ok = False
    else:
        print('negative dropped_chunk detected: %s' % errors[0])

    e = EarlyFinalPublisher(CHUNKS)
    if e.offer(0, CHUNKS[0]) != 'accepted':
        print('early final setup failed')
        return 1
    if e.offer(1, CHUNKS[1]) != 'accepted':
        print('early final setup failed')
        return 1
    if not e.finish('FINAL'):
        print('early final finish failed')
        return 1
    errors = verify(e.log, CHUNKS, 'FINAL')
    if not errors:
        print('negative control early final was not detected')
        ok = False
    else:
        print('negative early_final detected: %s' % errors[0])

    o = OverflowPublisher(CHUNKS)
    if not drive_to_final(o):
        print('overflow publisher drive failed')
        return 1
    errors = verify(o.log, CHUNKS, 'FINAL')
    if not errors:
        print('negative control overflow accept was not detected')
        ok = False
    else:
        print('negative overflow_accept detected: %s' % errors[0])

    if not ok:
        print('FAIL')
        return 1
    print('PASS: bounded queue, prefix, pause/resume and terminal invariants checked')
    return 0


if __name__ == '__main__':
    sys.exit(main())
